class ClientDashboardScreen extends StatefulWidget {
  final VoidCallback onLogout;
  const ClientDashboardScreen({super.key, required this.onLogout});

  @override
  State<ClientDashboardScreen> createState() => _ClientDashboardScreenState();
}

class _ClientDashboardScreenState extends State<ClientDashboardScreen> {
  int _currentIndex = 0;

  @override
  void initState() {
    super.initState();
    SystemChrome.setEnabledSystemUIMode(SystemUiMode.edgeToEdge);
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: const Color(0xFFF9F9F9), // Very light modern background
      extendBody: true, // Allow body to flow behind the floating nav bar
      body: SafeArea(
        bottom: false,
        child: IndexedStack(
          index: _currentIndex,
          children: [
            _HomeTab(
              onNavigate: (index) => setState(() => _currentIndex = index),
            ),
            _CarteTab(),
            const ExploreTab(),
            ClientProfileTab(onLogout: widget.onLogout),
          ],
        ),
      ),
      bottomNavigationBar: Container(
        padding: EdgeInsets.fromLTRB(12, 12, 12, 12 + MediaQuery.of(context).padding.bottom),
        decoration: BoxDecoration(
          color: const Color(0xFFFAF7F4).withOpacity(0.98), // RetenzaColors.paper
          border: const Border(
            top: BorderSide(color: Color(0x111B100C)),
          ),
        ),
        child: SafeArea(
          top: false,
          bottom: false, // Handled by padding above
          child: Row(
          mainAxisAlignment: MainAxisAlignment.spaceAround,
          children: [
            _buildNavItem(0, Icons.home_outlined),
            _buildNavItem(1, Icons.receipt_long_outlined),
            ElevatedButton.icon(
              onPressed: () {
                // TODO: ouvrir le scanner QR (mobile_scanner ou ÃƒÆ’Ã†â€™Ãƒâ€ Ã¢â‚¬â„¢ÃƒÆ’Ã¢â‚¬Å¡Ãƒâ€šÃ‚Â©quivalent)
              },
              icon: const Icon(Icons.qr_code_scanner, size: 16),
              label: const Text('Scan',
                  style: TextStyle(fontSize: 12, fontWeight: FontWeight.w600)),
              style: ElevatedButton.styleFrom(
                backgroundColor: const Color(0xFFD73E26), // RetenzaColors.grenadier
                foregroundColor: Colors.white,
                padding: const EdgeInsets.symmetric(horizontal: 18, vertical: 12),
                shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(100),
                ),
                elevation: 8,
                shadowColor: const Color(0xFFD73E26).withOpacity(0.4),
              ),
            ),
            _buildNavItem(2, Icons.explore_outlined),
            _buildNavItem(3, Icons.person_outline),
          ],
        ),
        ),
      ),
    );
  }

  Widget _buildNavItem(int index, IconData icon) {
    final isSelected = _currentIndex == index;
    final color = isSelected ? const Color(0xFFD73E26) : const Color(0xFF9C8B82); // grenadier / ink40
    
    return GestureDetector(
      onTap: () => setState(() => _currentIndex = index),
      behavior: HitTestBehavior.opaque,
      child: Padding(
        padding: const EdgeInsets.all(8.0),
        child: Icon(icon, color: color, size: 28),
      ),
    );
