            child: Icon(icon, color: iconColor, size: 28), // Dark icon
          ),
          const SizedBox(height: 8),
          Text(label, style: GoogleFonts.inter(fontSize: 12, fontWeight: FontWeight.w500, color: iconColor)),
        ],
      ),
    );
  }
