class _HistoryScreen extends ConsumerWidget {
  const _HistoryScreen();

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final dashboardAsync = ref.watch(clientDashboardProvider);

    return Scaffold(
      backgroundColor: const Color(0xFFF4EFEB),
      appBar: AppBar(
        backgroundColor: Colors.white,
        elevation: 0,
        iconTheme: const IconThemeData(color: Color(0xFF1B100C)),
        title: Text('Historique', style: GoogleFonts.bricolageGrotesque(color: const Color(0xFF1B100C), fontWeight: FontWeight.w700)),
      ),
      body: dashboardAsync.when(
        loading: () => const Center(child: CircularProgressIndicator(color: Color(0xFFD73E26))),
        error: (e, st) => Center(child: Text('Erreur: $e')),
        data: (data) {
          final transactions = List<dynamic>.from(data['lastTransactions'] ?? []);
          
          if (transactions.isEmpty) {
            return Center(child: Text('Aucun historique', style: GoogleFonts.inter(color: const Color(0xFF9C8B82))));
          }

          return ListView.builder(
            padding: const EdgeInsets.all(20),
            itemCount: transactions.length,
            itemBuilder: (context, index) {
              final tx = transactions[index];
              final amount = tx['amount'] ?? 0;
              final type = tx['type'] ?? 'earn';
              final isEarn = type == 'earn';
              final desc = tx['description'] ?? (isEarn ? 'Achat' : 'RÃƒÆ’Ã‚Â©compense utilisÃƒÆ’Ã‚Â©e');
              final dateStr = tx['createdAt'];
              final date = dateStr != null ? DateTime.parse(dateStr) : DateTime.now();
              final formattedDate = "${date.day.toString().padLeft(2, '0')}/${date.month.toString().padLeft(2, '0')} ÃƒÆ’Ã‚Â  ${date.hour.toString().padLeft(2, '0')}:${date.minute.toString().padLeft(2, '0')}";

              return Container(
                margin: const EdgeInsets.only(bottom: 12),
                padding: const EdgeInsets.all(16),
                decoration: BoxDecoration(
                  color: Colors.white,
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: const Color(0xFFEDE5DF)),
                ),
                child: Row(
                  children: [
                    Container(
                      padding: const EdgeInsets.all(10),
                      decoration: BoxDecoration(
                        color: isEarn ? const Color(0xFFE8F5E9) : const Color(0xFFFCE7DD),
                        shape: BoxShape.circle,
                      ),
                      child: Icon(
                        isEarn ? Icons.add_rounded : Icons.card_giftcard_rounded,
                        color: isEarn ? Colors.green : const Color(0xFFD73E26),
                        size: 20,
                      ),
                    ),
                    const SizedBox(width: 16),
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(desc, style: GoogleFonts.inter(fontSize: 14, fontWeight: FontWeight.w600, color: const Color(0xFF1B100C))),
                          Text(formattedDate, style: GoogleFonts.inter(fontSize: 12, color: const Color(0xFF9C8B82))),
                        ],
                      ),
                    ),
                    Text(
                      isEarn ? '+$amount pts' : '-$amount pts',
                      style: GoogleFonts.inter(
                        fontSize: 14,
                        fontWeight: FontWeight.w700,
                        color: isEarn ? Colors.green : const Color(0xFFD73E26),
                      ),
                    ),
                  ],
                ),
              );
            },
          );
        },
      ),
    );
