enum LoyaltyType { points, stamps, cashback }

class LoyaltyCard {
  final String clientId;
  final String merchantId;
  final String merchantName;
  final IconData icon;
  final LoyaltyType type;
  final DateTime? createdAt;
  final String? maskedNumber;

  // Points
  final int? currentPoints;
  final int? pointsGoal;

  // Stamps
  final int? stampsCollected;
  final int? stampsGoal;

  // Cashback
  final double? cashbackAmount;

  const LoyaltyCard({
    required this.clientId,
    required this.merchantId,
    required this.merchantName,
    required this.icon,
    required this.type,
    this.createdAt,
    this.maskedNumber,
    this.currentPoints,
    this.pointsGoal,
    this.stampsCollected,
    this.stampsGoal,
    this.cashbackAmount,
  });
}

class _CarteTab extends ConsumerStatefulWidget {
  @override
  ConsumerState<_CarteTab> createState() => _CarteTabState();
}

class _CarteTabState extends ConsumerState<_CarteTab> {
  static const Color grenadier = Color(0xFFD73E26);
  static const Color ink = Color(0xFF1A1512);
  static const Color muted = Color(0xFF8A8380);

  List<LoyaltyCard> _parseAccounts(List<dynamic> accounts) {
    return accounts.map((account) {
      final commerce = account['commerce'] ?? {};
      final merchantId = commerce['_id']?.toString() ?? '';
      final clientId = account['client'] is Map ? account['client']['_id']?.toString() ?? '' : account['client']?.toString() ?? '';
      final commerceName = commerce['name'] ?? 'Commerce';
      final programInfo = commerce['loyaltyProgram'] ?? {};
      final programTypeStr = programInfo['type'] ?? 'points';
      
      DateTime? createdAt;
      if (account['createdAt'] != null) {
        createdAt = DateTime.tryParse(account['createdAt'].toString());
      }

      final p = (account['points'] ?? 0) as int;
      final s = (account['stamps'] ?? 0) as int;
      final c = (account['cashbackBalance'] ?? 0.0).toDouble();

      if (programTypeStr == 'stamps') {
        return LoyaltyCard(
          clientId: clientId,
          merchantId: merchantId,
          merchantName: commerceName,
          createdAt: createdAt,
          icon: Icons.content_cut,
          type: LoyaltyType.stamps,
          stampsCollected: s,
          stampsGoal: 10,
        );
      } else if (programTypeStr == 'cashback') {
        return LoyaltyCard(
          clientId: clientId,
          merchantId: merchantId,
          merchantName: commerceName,
          createdAt: createdAt,
          icon: Icons.restaurant,
          type: LoyaltyType.cashback,
          cashbackAmount: c,
        );
      } else {
        final goal = programInfo['pointsPerEuro'] != null ? 500 : 300;
        return LoyaltyCard(
          clientId: clientId,
          merchantId: merchantId,
          merchantName: commerceName,
          createdAt: createdAt,
          icon: Icons.bakery_dining,
          type: LoyaltyType.points,
          currentPoints: p,
          pointsGoal: goal,
          maskedNumber: '**** **** **** 4471',
        );
      }
    }).toList();
  }

